  54:     private final MediaRuntimeDiagnostics diagnostics = new MediaRuntimeDiagnostics(catalog, telemetry, observers, history);
  55:     private final AudioFocusBoundary focus;
  56:     private PlaybackSnapshot snapshot = PlaybackSnapshot.disconnected();
  57:     public PlaybackSessionRuntime(Context context) { focus = new AudioFocusBoundary((AudioManager) context.getSystemService(Context.AUDIO_SERVICE), this); catalog.addObserver(searchIndex::rebuild); }
  58:     public synchronized PlaybackSnapshot snapshot() { return snapshot; }
  59:     public synchronized PlaybackSnapshot dispatch(PlaybackCommand command, List<String> queue) {
  60:         if (command.sequence() <= sequences.get()) throw new IllegalArgumentException("stale command");
  61:         sequences.set(command.sequence());
  62:         if (command.type() == PlaybackCommand.Type.PLAY && !focus.request()) throw new IllegalStateException("audio focus denied");
