  26: import java.util.Map;
  27: import java.util.Objects;
  28: import java.util.concurrent.CopyOnWriteArrayList;
  29: 
  30: public final class MediaCatalogRepository {
  31:     private final Object lock = new Object();
  32:     private final Clock clock;
  33:     private final Map<String, MediaCatalogItem> items = new LinkedHashMap<>();
  34:     private final CopyOnWriteArrayList<MediaCatalogObserver> observers =
  35:             new CopyOnWriteArrayList<>();
  36:     private long generation;
  37: 
  38:     public MediaCatalogRepository(Clock clock) {
  39:         this.clock = Objects.requireNonNull(clock, "clock");
  40:     }
  41: 
  42:     public MediaCatalogSnapshot replace(List<MediaCatalogItem> incoming) {
  43:         MediaCatalogSnapshot snapshot;
  44:         synchronized (lock) {
  45:             Map<String, MediaCatalogItem> replacement = new LinkedHashMap<>();
  46:             for (MediaCatalogItem item : incoming) {
  47:                 MediaCatalogItem previous = replacement.put(item.id(), item);
  48:                 if (previous != null) {
  49:                     throw new IllegalArgumentException("duplicate media id " + item.id());
  50:                 }
  51:             }
  52:             items.clear();
  53:             items.putAll(replacement);
  54:             generation += 1;
  55:             snapshot = snapshotLocked();
  56:         }
  57:         notifyObservers(snapshot);
  58:         return snapshot;
  59:     }
  60: 
  61:     public MediaCatalogSnapshot upsert(MediaCatalogItem item) {
  62:         MediaCatalogSnapshot snapshot;
  63:         synchronized (lock) {
  64:             items.put(item.id(), item);
  65:             generation += 1;
  66:             snapshot = snapshotLocked();
  67:         }
  68:         notifyObservers(snapshot);
  69:         return snapshot;
  70:     }
  71: 
  72:     public MediaCatalogSnapshot remove(String id) {
  73:         MediaCatalogSnapshot snapshot;
  74:         synchronized (lock) {
  75:             if (items.remove(id) != null) {
  76:                 generation += 1;
  77:             }
  78:             snapshot = snapshotLocked();
  79:         }
  80:         notifyObservers(snapshot);
  81:         return snapshot;
  82:     }
  83: 
  84:     public List<MediaCatalogItem> search(String query, int limit) {
  85:         if (limit < 1) {
  86:             return Collections.emptyList();
  87:         }
  88:         String needle = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
  89:         List<MediaCatalogItem> result = new ArrayList<>();
  90:         synchronized (lock) {
  91:             for (MediaCatalogItem item : items.values()) {
  92:                 String haystack = (item.title() + " " + item.artist()).toLowerCase(Locale.ROOT);
  93:                 if (needle.isEmpty() || haystack.contains(needle)) {
  94:                     result.add(item);
  95:                     if (result.size() == limit) break;
  96:                 }
  97:             }
  98:         }
  99:         return Collections.unmodifiableList(result);
 100:     }
 101: 
 102:     public MediaCatalogSnapshot snapshot() {
 103:         synchronized (lock) {
 104:             return snapshotLocked();
 105:         }
 106:     }
 107: 
 108:     public void addObserver(MediaCatalogObserver observer) { observers.addIfAbsent(observer); }
 109:     public void removeObserver(MediaCatalogObserver observer) { observers.remove(observer); }
 110: 
 111:     private MediaCatalogSnapshot snapshotLocked() {
 112:         Instant now = clock.instant();
 113:         return new MediaCatalogSnapshot(generation, now, new ArrayList<>(items.values()));
 114:     }
 115: 
 116:     private void notifyObservers(MediaCatalogSnapshot snapshot) {
 117:         for (MediaCatalogObserver observer : observers) {
 118:             observer.onCatalogChanged(snapshot);
 119:         }
 120:     }
 121: }
