  16: 
  17: package com.cockpitbench.wavemedia;
  18: 
  19: import android.media.AudioAttributes;
  20: import android.media.AudioFocusRequest;
  21: import android.media.AudioManager;
  22: 
  23: public final class AudioFocusBoundary implements AudioManager.OnAudioFocusChangeListener {
  24:     public interface Listener { void onFocusGained(); void onFocusLost(boolean transientLoss); void onDuck(boolean duck); }
  25:     private final AudioManager audioManager;
  26:     private final Listener listener;
  27:     private final AudioFocusRequest request;
  28:     private boolean held;
  29:     public AudioFocusBoundary(AudioManager audioManager, Listener listener) {
  30:         this.audioManager = audioManager;
  31:         this.listener = listener;
  32:         AudioAttributes attributes = new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build();
  33:         request = new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(attributes).setOnAudioFocusChangeListener(this).setWillPauseWhenDucked(false).build();
  34:     }
  35:     public boolean request() {
  36:         held = audioManager.requestAudioFocus(request) == AudioManager.AUDIOFOCUS_REQUEST_GRANTED;
  37:         return held;
  38:     }
  39:     public void abandon() {
  40:         if (held) audioManager.abandonAudioFocusRequest(request);
  41:         held = false;
  42:     }
  43:     public boolean isHeld() { return held; }
  44:     @Override public void onAudioFocusChange(int focusChange) {
  45:         if (focusChange == AudioManager.AUDIOFOCUS_GAIN) { held = true; listener.onDuck(false); listener.onFocusGained(); }
  46:         else if (focusChange == AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK) listener.onDuck(true);
  47:         else if (focusChange == AudioManager.AUDIOFOCUS_LOSS_TRANSIENT) { held = false; listener.onFocusLost(true); }
  48:         else if (focusChange == AudioManager.AUDIOFOCUS_LOSS) { held = false; listener.onFocusLost(false); }
  49:     }
  50: }
