  17: package com.cockpitbench.wavemedia;
  18: 
  19: import java.util.HashSet;
  20: import java.util.Set;
  21: 
  22: public final class DrivingPlaybackPolicy {
  23:     private final Set<String> unavailableSources = new HashSet<>();
  24: 
  25:     public synchronized void sourceUnavailable(String source) {
  26:         unavailableSources.add(source);
  27:     }
  28: 
  29:     public synchronized void sourceAvailable(String source) {
  30:         unavailableSources.remove(source);
  31:     }
  32: 
  33:     public synchronized PlaybackEligibility evaluate(MediaCatalogItem item,
  34:             PlaybackPolicyContext context) {
  35:         if (unavailableSources.contains(item.source())) {
  36:             return PlaybackEligibility.denied(
  37:                     PlaybackEligibility.Reason.SOURCE_UNAVAILABLE,
  38:                     "source unavailable: " + item.source());
  39:         }
  40:         if (context.parentalControl() && item.explicit()) {
  41:             return PlaybackEligibility.denied(
  42:                     PlaybackEligibility.Reason.EXPLICIT_CONTENT,
  43:                     "explicit content blocked");
  44:         }
  45:         if (context.role() == PlaybackPolicyContext.OccupantRole.DRIVER
  46:                 && !context.parked()
  47:                 && context.speedKph() > 0
  48:                 && !context.distractionOptimized()) {
  49:             return PlaybackEligibility.denied(
  50:                     PlaybackEligibility.Reason.DRIVER_DISTRACTION,
  51:                     "driver content is not distraction optimized");
  52:         }
  53:         return PlaybackEligibility.allowed();
  54:     }
  55: }
