  15:  */
  16: 
  17: package com.cockpitbench.wavemedia;
  18: 
  19: import java.util.List;
  20: 
  21: public final class PlaybackReducer {
  22:     public PlaybackSnapshot reduce(PlaybackSnapshot current, PlaybackCommand command, List<String> requestedQueue) {
  23:         switch (command.type()) {
  24:             case PREPARE:
  25:                 return current.with(PlaybackSnapshot.State.READY, command.mediaId(), 0, null);
  26:             case PLAY:
  27:                 requireReady(current);
  28:                 return current.with(PlaybackSnapshot.State.PLAYING, current.mediaId(), current.positionMillis(), null);
  29:             case PAUSE:
  30:                 requireState(current, PlaybackSnapshot.State.PLAYING);
  31:                 return current.with(PlaybackSnapshot.State.PAUSED, current.mediaId(), current.positionMillis(), null);
  32:             case STOP:
  33:                 return current.with(PlaybackSnapshot.State.READY, current.mediaId(), 0, null);
  34:             case SEEK:
  35:                 requireReady(current);
  36:                 return current.with(current.state(), current.mediaId(), command.positionMillis(), null);
  37:             case SKIP_NEXT:
  38:                 return skip(current, 1);
  39:             case SKIP_PREVIOUS:
  40:                 return skip(current, -1);
  41:             case SET_QUEUE:
  42:                 if (requestedQueue == null) throw new IllegalArgumentException("queue is required");
  43:                 return current.withQueue(requestedQueue);
  44:             default:
  45:                 throw new IllegalStateException("unknown command " + command.type());
  46:         }
  47:     }
  48:     private PlaybackSnapshot skip(PlaybackSnapshot current, int delta) {
  49:         if (current.queue().isEmpty()) return current;
  50:         int index = Math.max(0, current.queue().indexOf(current.mediaId()));
  51:         int next = Math.floorMod(index + delta, current.queue().size());
  52:         return current.with(PlaybackSnapshot.State.READY, current.queue().get(next), 0, null);
  53:     }
  54:     private void requireReady(PlaybackSnapshot state) {
  55:         if (state.state() != PlaybackSnapshot.State.READY && state.state() != PlaybackSnapshot.State.PAUSED && state.state() != PlaybackSnapshot.State.PLAYING) {
  56:             throw new IllegalStateException("playback is not ready: " + state.state());
  57:         }
  58:     }
  59:     private void requireState(PlaybackSnapshot state, PlaybackSnapshot.State required) {
  60:         if (state.state() != required) throw new IllegalStateException("required " + required + " but was " + state.state());
  61:     }
  62: }
