  22: import java.util.concurrent.CopyOnWriteArrayList;
  23: 
  24: public final class SessionObserverRegistry {
  25:     private final CopyOnWriteArrayList<MediaSessionObserver> observers =
  26:             new CopyOnWriteArrayList<>();
  27: 
  28:     public boolean add(MediaSessionObserver observer) {
  29:         return observers.addIfAbsent(Objects.requireNonNull(observer, "observer"));
  30:     }
  31: 
  32:     public boolean remove(MediaSessionObserver observer) {
  33:         return observers.remove(observer);
  34:     }
  35: 
  36:     public void publish(MediaSessionEvent event) {
  37:         List<RuntimeException> failures = new ArrayList<>();
  38:         for (MediaSessionObserver observer : observers) {
  39:             try {
  40:                 observer.onSessionEvent(event);
  41:             } catch (RuntimeException failure) {
  42:                 failures.add(failure);
  43:             }
  44:         }
  45:         if (!failures.isEmpty()) {
  46:             IllegalStateException combined = new IllegalStateException(
  47:                     failures.size() + " session observers failed");
  48:             for (RuntimeException failure : failures) {
  49:                 combined.addSuppressed(failure);
  50:             }
  51:             throw combined;
  52:         }
  53:     }
  54: 
  55:     public int size() { return observers.size(); }
  56:     public void clear() { observers.clear(); }
  57: }
