  16: 
  17: package com.cockpitbench.wavemedia;
  18: 
  19: import java.util.ArrayList;
  20: import java.util.LinkedHashSet;
  21: import java.util.List;
  22: import java.util.Set;
  23: 
  24: public final class QueueCoordinator {
  25:     private final int maximumItems;
  26:     public QueueCoordinator(int maximumItems) {
  27:         if (maximumItems < 1) throw new IllegalArgumentException("maximumItems");
  28:         this.maximumItems = maximumItems;
  29:     }
  30:     public List<String> normalize(List<String> requested, String currentMediaId) {
  31:         Set<String> unique = new LinkedHashSet<>();
  32:         if (currentMediaId != null && !currentMediaId.isEmpty()) unique.add(currentMediaId);
  33:         for (String mediaId : requested) {
  34:             if (mediaId == null || mediaId.trim().isEmpty()) continue;
  35:             unique.add(mediaId.trim());
  36:             if (unique.size() == maximumItems) break;
  37:         }
  38:         return new ArrayList<>(unique);
  39:     }
  40:     public List<String> move(List<String> queue, int from, int to) {
  41:         if (from < 0 || from >= queue.size() || to < 0 || to >= queue.size()) throw new IndexOutOfBoundsException();
  42:         List<String> copy = new ArrayList<>(queue);
  43:         String value = copy.remove(from);
  44:         copy.add(to, value);
  45:         return copy;
  46:     }
  47:     public List<String> remove(List<String> queue, String mediaId) {
  48:         List<String> copy = new ArrayList<>(queue);
  49:         copy.removeIf(item -> item.equals(mediaId));
  50:         return copy;
  51:     }
  52: }
