  24: public final class MediaSourceRegistry {
  25:     public static final class Source {
  26:         public final String id; public final String packageName; public final boolean browse; public final boolean playback;
  27:         public Source(String id, String packageName, boolean browse, boolean playback) { this.id=id; this.packageName=packageName; this.browse=browse; this.playback=playback; }
  28:     }
  29:     private final Map<String, Source> sources = new LinkedHashMap<>();
  30:     public synchronized void replace(List<Source> values) { sources.clear(); for (Source value : values) sources.put(value.id, value); }
  31:     public synchronized Source require(String id) { Source value=sources.get(id); if(value==null) throw new IllegalArgumentException("unknown source " + id); return value; }
  32:     public synchronized List<Source> browsable() { List<Source> result=new ArrayList<>(); for(Source value:sources.values()) if(value.browse) result.add(value); return result; }
  33:     public synchronized List<Source> playable() { List<Source> result=new ArrayList<>(); for(Source value:sources.values()) if(value.playback) result.add(value); return result; }
