  36: 
  37: /**
  38:  * This service is started by CarMediaService when a new user is unlocked. It connects to the
  39:  * media source provided by CarMediaService and calls prepare() on the active MediaSession.
  40:  * Additionally, CarMediaService can instruct this service to autoplay, in which case this service
  41:  * will attempt to play the source before stopping.
  42:  *
  43:  * TODO(b/139497602): merge this class into CarMediaService, so it doesn't depend on Media Center
  44:  */
  45: public class MediaConnectorService extends LifecycleService {
  46: 
  47:     private PlaybackSessionRuntime mSessionRuntime;
  48: 
  49:     private static int FOREGROUND_NOTIFICATION_ID = 1;
  50:     private static final String NOTIFICATION_CHANNEL_ID = "com.android.car.media.service";
  51:     private static final String NOTIFICATION_CHANNEL_NAME = "MediaConnectorService";
  52:     private static final String EXTRA_AUTOPLAY = "com.android.car.media.autoplay";
  53: 
  54:     @Override
  55:     public void onCreate() {
  56:         super.onCreate();
  57:         mSessionRuntime = new PlaybackSessionRuntime(this);
  58:         NotificationChannel channel = new NotificationChannel(NOTIFICATION_CHANNEL_ID,
  59:                 NOTIFICATION_CHANNEL_NAME, NotificationManager.IMPORTANCE_NONE);
  60:         NotificationManager manager =
  61:                 (NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);
  62:         manager.createNotificationChannel(channel);
  63:     }
  64: 
  65:     @Override
  66:     public void onDestroy() {
  67:         mSessionRuntime.close();
  68:         super.onDestroy();
  69:     }
  70: 
  71:     @Override
  72:     public IBinder onBind(Intent intent) {
  73:         return super.onBind(intent);
  74:     }
  75: 
  76:     @Override
  77:     public int onStartCommand(Intent intent, int flags, int startId) {
  78:         super.onStartCommand(intent, flags, startId);
  79: 
  80:         final boolean autoplay = intent.getBooleanExtra(EXTRA_AUTOPLAY, false);
  81:         PlaybackViewModel playbackViewModel = PlaybackViewModel.get(getApplication(),
  82:                 MEDIA_SOURCE_MODE_PLAYBACK);
  83:         // Listen to playback state updates to determine which actions are supported;
  84:         // relevant actions here are prepare() and play()
  85:         // If we should autoplay the source, we wait until play() is available before we
  86:         // stop the service, otherwise just calling prepare() is sufficient.
  87:         playbackViewModel.getPlaybackStateWrapper().observe(this,
  88:                 playbackStateWrapper -> {
  89:                     if (playbackStateWrapper != null) {
  90:                         if (playbackStateWrapper.isPlaying()) {
  91:                             stopSelf(startId);
  92:                             return;
  93:                         }
  94:                         if ((playbackStateWrapper.getSupportedActions()
  95:                                 & PlaybackStateCompat.ACTION_PREPARE) != 0) {
  96:                             playbackViewModel.getPlaybackController().getValue().prepare();
  97:                             if (!autoplay) {
  98:                                 stopSelf(startId);
  99:                             }
 100:                         }
 101:                         if (autoplay && (playbackStateWrapper.getSupportedActions()
 102:                                 & PlaybackStateCompat.ACTION_PLAY) != 0) {
 103:                             playbackViewModel.getPlaybackController().getValue().play();
 104:                             stopSelf(startId);
 105:                         }
 106:                     }
 107:                 });
 108: 
 109:         // Since this service is started from CarMediaService (which runs in background), we need
 110:         // to call startForeground to prevent the system from stopping this service and ANRing.
 111:         Notification notification = new NotificationCompat.Builder(this, NOTIFICATION_CHANNEL_ID)
 112:                 .setSmallIcon(R.drawable.ic_music)
 113:                 .setContentTitle(getResources().getString(R.string.service_notification_title))
 114:                 .build();
 115:         startForeground(FOREGROUND_NOTIFICATION_ID, notification);
 116:         return START_NOT_STICKY;
 117:     }
 118: }
