  95:                                 & PlaybackStateCompat.ACTION_PREPARE) != 0) {
  96:                             playbackViewModel.getPlaybackController().getValue().prepare();
  97:                             if (!autoplay) {
  98:                                 stopSelf(startId);
  99:                             }
 100:                         }
 101:                         if (autoplay && (playbackStateWrapper.getSupportedActions()
 102:                                 & PlaybackStateCompat.ACTION_PLAY) != 0) {
 103:                             playbackViewModel.getPlaybackController().getValue().play();
 104:                             stopSelf(startId);
 105:                         }
 106:                     }
 107:                 });
