 109:         // Since this service is started from CarMediaService (which runs in background), we need
 110:         // to call startForeground to prevent the system from stopping this service and ANRing.
 111:         Notification notification = new NotificationCompat.Builder(this, NOTIFICATION_CHANNEL_ID)
 112:                 .setSmallIcon(R.drawable.ic_music)
 113:                 .setContentTitle(getResources().getString(R.string.service_notification_title))
 114:                 .build();
 115:         startForeground(FOREGROUND_NOTIFICATION_ID, notification);
 116:         return START_NOT_STICKY;
 117:     }
